class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_pending_order_id = None
        self.aapl_pending_order_id = None

        # The extra sample permits the first post-warm-up bar to test a cross
        # using two fully formed 100-day SMA values.
        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        # State is updated from every available bar, even when another ticker
        # is absent and the day's trading rules must consequently be skipped.
        if data.Bars.ContainsKey(spy):
            spy_bar = data.Bars[spy]
            prior_spy_close = self.previous_spy_close
            prior_spy_sma = self.previous_spy_sma
            self.spy_sma.Update(data.Time, spy_bar.Close)
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = self.spy_sma.Current.Value
        else:
            prior_spy_close = None
            prior_spy_sma = None

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_bar.Close
            self.aapl_rsi.Update(data.Time, aapl_bar.Close)

        if self.IsWarmingUp:
            return

        # Every subscribed ticker must have today's TradeBar before either
        # independent strategy is allowed to evaluate a rule.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        # Sells are evaluated before buys. Each ticker is used by exactly one
        # strategy, so its holding is that strategy's private lot.
        if self.Portfolio[spy].Quantity > 0 and self.spy_pending_order_id is None:
            crossed_below = (
                prior_spy_close is not None
                and prior_spy_sma is not None
                and prior_spy_close >= prior_spy_sma
                and data.Bars[spy].Close < self.spy_sma.Current.Value
            )
            if crossed_below:
                ticket = self.MarketOrder(spy, -self.Portfolio[spy].Quantity)
                self.spy_pending_order_id = ticket.OrderId

        if self.Portfolio[aapl].Quantity > 0 and self.aapl_pending_order_id is None:
            if self.aapl_rsi.Current.Value > 60:
                ticket = self.MarketOrder(aapl, -self.Portfolio[aapl].Quantity)
                self.aapl_pending_order_id = ticket.OrderId

        if not self.Portfolio[spy].Invested and self.spy_pending_order_id is None:
            crossed_above = (
                prior_spy_close is not None
                and prior_spy_sma is not None
                and prior_spy_close <= prior_spy_sma
                and data.Bars[spy].Close > self.spy_sma.Current.Value
            )
            if crossed_above:
                quantity = self.CalculateOrderQuantity(spy, 0.40)
                if quantity > 0:
                    ticket = self.MarketOrder(spy, quantity)
                    self.spy_pending_order_id = ticket.OrderId

        if not self.Portfolio[aapl].Invested and self.aapl_pending_order_id is None:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                quantity = floor(20_000 / data.Bars[aapl].Close)
                if quantity > 0:
                    ticket = self.MarketOrder(aapl, quantity)
                    self.aapl_pending_order_id = ticket.OrderId

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            return

        if order_event.OrderId == self.spy_pending_order_id:
            self.spy_pending_order_id = None
        if order_event.OrderId == self.aapl_pending_order_id:
            self.aapl_pending_order_id = None

