            quantity = math.floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close)
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.spy_lot = quantity

        # Strategy B: RSI is fully formed before either of its rules may trade.
        if self.aapl_lot > 0 and float(self.aapl_rsi.Current.Value) > 60.0:
            self.MarketOrder(aapl, -self.aapl_lot)
            self.aapl_lot = 0
        elif self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000.0
            if float(self.Portfolio.Cash) >= cash_to_invest:
                quantity = math.floor(cash_to_invest / aapl_close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.aapl_lot = quantity
